function buildReal(id, grade, label, data, subject) {
  return {
    id,
    grade,
    label,
    ...subject ? { subject } : {},
    units: data.map((u, ui) => ({
      id: `${id}-u${ui}`,
      name: u[0],
      mids: u[1].map((m, mi) => ({
        id: `${id}-u${ui}m${mi}`,
        name: m[0],
        subs: m[1].map((s, si) => ({
          id: `${id}-u${ui}m${mi}s${si}`,
          name: s[0],
          types: s[1].map((t) => ({ id: t[0], name: t[1] }))
        }))
      }))
    }))
  };
}
